#import "RNKlineComponentView.h"

#import <react/renderer/components/RNKlineSpec/ComponentDescriptors.h>
#import <react/renderer/components/RNKlineSpec/EventEmitters.h>
#import <react/renderer/components/RNKlineSpec/Props.h>
#import <react/renderer/components/RNKlineSpec/RCTComponentViewHelpers.h>

// Swift bridge (module name defined in the podspec).
#import "RNKline-Swift.h"

using namespace facebook::react;

namespace {

// The codegen-generated ByronKlineDatasStruct has no operator==, so compare
// element-wise (all fields) to detect real data changes.
bool RNKLArraysEqual(const std::vector<ByronKlineDatasStruct> &a,
                     const std::vector<ByronKlineDatasStruct> &b)
{
  if (a.size() != b.size()) {
    return false;
  }
  for (size_t i = 0; i < a.size(); i++) {
    const auto &x = a[i];
    const auto &y = b[i];
    if (x.id != y.id || x.open != y.open || x.high != y.high || x.low != y.low ||
        x.close != y.close || x.vol != y.vol || x.amount != y.amount) {
      return false;
    }
  }
  return true;
}

} // namespace

@interface RNKlineComponentView () <RCTByronKlineViewProtocol>
@end

@implementation RNKlineComponentView {
  RNKlineChartController *_controller;
}

- (instancetype)initWithFrame:(CGRect)frame
{
  if (self = [super initWithFrame:frame]) {
    static const auto defaultProps = std::make_shared<const ByronKlineProps>();
    _props = defaultProps;

    _controller = [[RNKlineChartController alloc] initWithFrame:frame];
    __weak __typeof(self) weakSelf = self;
    _controller.onMoreKLineDataHandler = ^(double dataId) {
      [weakSelf emitOnMoreKLineDataWithId:dataId];
    };
    [self addSubview:_controller];
  }
  return self;
}

#pragma mark - Props

/**
 * Note: the legacy iOS implementation only ever consumed a subset of the
 * exported props (the rest were stored on the controller and never read).
 * To keep behavior identical, only that subset is forwarded here.
 */
- (void)updateProps:(Props::Shared const &)props oldProps:(Props::Shared const &)oldProps
{
  const auto &oldViewProps = *std::static_pointer_cast<ByronKlineProps const>(_props);
  const auto &newViewProps = *std::static_pointer_cast<ByronKlineProps const>(props);

#define RNKL_STR(prop) \
  if (oldViewProps.prop != newViewProps.prop) { \
    _controller.prop = [NSString stringWithUTF8String:newViewProps.prop.c_str()]; \
  }

  RNKL_STR(mainBackgroundColor)
  RNKL_STR(increaseColor)
  RNKL_STR(decreaseColor)
  RNKL_STR(ma1Color)
  RNKL_STR(ma2Color)
  RNKL_STR(ma3Color)
  RNKL_STR(limitTextColor)

  if (oldViewProps.pricePrecision != newViewProps.pricePrecision) {
    _controller.pricePrecision = @(newViewProps.pricePrecision);
  }
  if (oldViewProps.volumePrecision != newViewProps.volumePrecision) {
    _controller.volumePrecision = @(newViewProps.volumePrecision);
  }

  if (!RNKLArraysEqual(oldViewProps.datas, newViewProps.datas)) {
    NSMutableArray *datas = [NSMutableArray arrayWithCapacity:newViewProps.datas.size()];
    for (const auto &item : newViewProps.datas) {
      [datas addObject:@{
        @"id": @(item.id),
        @"open": @(item.open),
        @"high": @(item.high),
        @"low": @(item.low),
        @"close": @(item.close),
        @"vol": @(item.vol),
        @"amount": @(item.amount),
      }];
    }
    [_controller setDatas:datas];
  }

  if (oldViewProps.locales != newViewProps.locales) {
    NSMutableArray *locales = [NSMutableArray arrayWithCapacity:newViewProps.locales.size()];
    for (const auto &item : newViewProps.locales) {
      [locales addObject:[NSString stringWithUTF8String:item.c_str()]];
    }
    [_controller setLocales:locales];
  }

  if (oldViewProps.indicators != newViewProps.indicators) {
    NSMutableArray *indicators = [NSMutableArray arrayWithCapacity:newViewProps.indicators.size()];
    for (const auto &item : newViewProps.indicators) {
      [indicators addObject:@(item)];
    }
    [_controller setIndicators:indicators];
  }

  [super updateProps:props oldProps:oldProps];
}

#pragma mark - Commands

- (void)handleCommand:(NSString *)commandName args:(NSArray *)args
{
  RCTByronKlineHandleCommand(self, commandName, args);
}

- (void)byronController:(NSString *)event list:(const NSArray *)list
{
  [_controller handleCommandWithEvent:event list:list ? [list copy] : @[]];
}

#pragma mark - Events

- (void)emitOnMoreKLineDataWithId:(double)dataId
{
  if (_eventEmitter) {
    ByronKlineEventEmitter::OnMoreKLineData payload{};
    payload.id = dataId;
    static_cast<const ByronKlineEventEmitter &>(*_eventEmitter)
        .onMoreKLineData(std::move(payload));
  }
}

#pragma mark - Layout

- (void)layoutSubviews
{
  [super layoutSubviews];
  _controller.frame = self.bounds;
}

+ (ComponentDescriptorProvider)componentDescriptorProvider
{
  return concreteComponentDescriptorProvider<ByronKlineComponentDescriptor>();
}

@end

// Required by the codegen-generated RCTThirdPartyFabricComponentsProvider
// (from codegenConfig.ios.componentProvider: {"ByronKline": "RNKlineComponentView"}).
extern "C" Class<RCTComponentViewProtocol> ByronKlineCls(void)
{
  return RNKlineComponentView.class;
}
